begin;

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('577', 'ㅊㅊ', 'Chu-Cheon', 'consonant', 'frequently-used', '추천 — 이거 좋다고 권할 때 (문맥 따라 축하·출첵도)', '{"de": "추천 (empfehlen) — etwas ans Herz legen; je nach Kontext auch 축하 oder 출첵", "en": "추천 (recommend) — vouching for something; context can also make it 축하 or 출첵", "es": "추천 (recomiendo) — para avalar algo; según contexto también 축하 o 출첵", "ja": "추천(おすすめ) — 勧めるとき。文脈により축하(お祝い)・출첵(出席チェック)にもなる", "vi": "추천 (giới thiệu) — khi gợi ý cái gì hay; tùy ngữ cảnh còn là 축하 hoặc 출첵"}'::jsonb, '[추-천]', '[{"type": "명사/감탄사", "examples": [{"de": "Empfiehl mir Filme fürs Wochenende.", "es": "Recomiéndame pelis para el finde.", "ja": "週末に見る映画、おすすめ教えて。", "vi": "Gợi ý cho tớ phim xem cuối tuần với.", "eng": "Give me some movie recs for the weekend.", "kor": "주말에 볼 영화 ㅊㅊ 좀 해줘."}, {"de": "Dieses Café kann ich echt empfehlen — die Desserts sind der Wahnsinn.", "es": "Recomiendo mucho este café, los postres son una locura.", "ja": "このカフェ本当におすすめ。デザートがやばい。", "vi": "Quán cafe này tớ giới thiệu thật, tráng miệng đỉnh lắm.", "eng": "Highly recommend this cafe — the desserts are insane.", "kor": "이 카페 진짜 ㅊㅊ. 디저트가 미쳤어."}], "definition": "보통 ''추천''의 초성만 딴 말로, 좋은 걸 권하거나 남에게 추천을 부탁할 때 쓴다. 다만 같은 ㅊㅊ가 문맥에 따라 ''축하''(축하의 ㅊㅋㅊㅋ를 줄인 형태)나 ''출첵(출석 체크)''으로도 읽히므로, 글 종류를 보고 구분해야 한다 — 맛집·영화 글이면 추천, 합격·생일 글이면 축하, 매일 올라오는 게시판 글이면 출첵일 가능성이 높다.", "definition_i18n": {"de": "Meist die Anfangskonsonanten von 추천 (\"empfehlen\") — etwas loben oder um Vorschläge bitten. Dasselbe ㅊㅊ kann aber 축하 (\"Glückwunsch\", verkürzt aus ㅊㅋㅊㅋ) oder 출첵 (\"Anwesenheit\") heißen; richte dich nach dem Thread: Essen und Filme heißt empfehlen, bestandene Prüfung oder Geburtstag heißt gratulieren, tägliche Forenthreads heißt einchecken.", "en": "Usually the initial consonants of 추천 (\"recommend\") — vouching for something or asking others to suggest one. But the same ㅊㅊ can read as 축하 (\"congrats\", shortened from ㅊㅋㅊㅋ) or 출첵 (\"roll call\"), so judge by the post: food and film threads mean recommend, pass-the-exam or birthday posts mean congrats, daily forum threads mean checking in.", "es": "Normalmente son las consonantes de 추천 (\"recomiendo\"): avalar algo o pedir sugerencias. Pero el mismo ㅊㅊ puede leerse como 축하 (\"felicidades\", acortado de ㅊㅋㅊㅋ) o 출첵 (\"pasar lista\"), así que fíjate en el hilo: comida y cine, recomendar; aprobados y cumpleaños, felicitar; hilos diarios, registrarse.", "ja": "普通は「추천(おすすめ)」の初声で、良いものを勧めたり勧めてほしいと頼むときに使う。ただし同じㅊㅊが文脈により「축하(お祝い、ㅊㅋㅊㅋを縮めた形)」や「출첵(出席チェック)」とも読まれるので、投稿の種類で見分ける — グルメ・映画なら推薦、合格・誕生日ならお祝い、毎日上がる掲示板なら出席チェックの可能性が高い。", "vi": "Thường là phụ âm đầu của 추천 (\"giới thiệu\") — khen một thứ hoặc nhờ người khác gợi ý. Nhưng cùng ㅊㅊ có thể là 축하 (\"chúc mừng\", rút gọn từ ㅊㅋㅊㅋ) hoặc 출첵 (\"điểm danh\"), nên xem loại bài: bài ăn uống, phim thì là giới thiệu; bài đỗ, sinh nhật thì là chúc mừng; bài diễn đàn hằng ngày thì là điểm danh."}}]'::jsonb, '''추천''의 초성 ㅊ·ㅊ만 남긴 말. 게시판에 추천 버튼이 있던 시절 댓글로 ''추천''을 대신 적던 관행에서 굳어진 것으로 설명되지만, 최초 시점을 특정한 자료는 없다. ''축하''로 읽는 용법은 별개 경로로, 축하를 뜻하는 ㅊㅋㅊㅋ를 한 번 더 줄여 ㅊㅊ가 된 것이다.', '{"de": "Anfangskonsonanten von 추천. Es soll sich eingebürgert haben, als man in Foren mit Upvote-Button 추천 in die Kommentare tippte; ein Datum nennt keine Quelle. Die Lesart 축하 kam auf anderem Weg: ㅊㅋㅊㅋ (Glückwunsch, Glückwunsch) wurde noch einmal zu ㅊㅊ verkürzt.", "en": "Initial consonants of 추천. It is said to have settled in from the habit of typing 추천 in comments back when boards had an upvote button, but no source pins a date. The 축하 reading came by a separate route: ㅊㅋㅊㅋ (congrats congrats) shortened once more to ㅊㅊ.", "es": "Consonantes iniciales de 추천. Se dice que cuajó por la costumbre de escribir 추천 en los comentarios cuando los foros tenían botón de voto, pero ninguna fuente da fecha. La lectura 축하 vino por otra vía: ㅊㅋㅊㅋ (felicidades, felicidades) se acortó otra vez a ㅊㅊ.", "ja": "「추천」の初声。掲示板に推薦ボタンがあった時代、コメントに「추천」と書く習慣から定着したと説明されるが、時期を特定した資料はない。「축하」と読む用法は別経路で、お祝いのㅊㅋㅊㅋをさらに縮めてㅊㅊになったもの。", "vi": "Phụ âm đầu của 추천. Được cho là hình thành từ thói quen gõ 추천 trong bình luận thời diễn đàn có nút bình chọn, nhưng không nguồn nào xác định thời điểm. Cách đọc 축하 đến từ đường khác: ㅊㅋㅊㅋ (chúc mừng chúc mừng) được rút gọn thêm lần nữa thành ㅊㅊ."}'::jsonb, '추천 요청 글의 제목이나 댓글에서 거의 관용구처럼 쓰인다(''저녁 메뉴 ㅊㅊ''). 뜻이 셋으로 갈리는 초성체라, 외국인 학습자에게는 헷갈릴 때 그냥 ''''추천해줘''''라고 풀어 쓰라고 권한다. 짝이 되는 반대말은 없고, 별로일 때는 ㅂㅊ(비추)를 쓴다.', '{"de": "Fast formelhaft in Titeln und Kommentaren von Empfehlungs-Threads (저녁 메뉴 ㅊㅊ = \"Abendessen-Tipps?\"). Da es dreifach gelesen werden kann, schreiben Lernende im Zweifel besser 추천해줘 aus. Ein festes Gegenstück gibt es nicht; zum Abraten nutzt man ㅂㅊ (비추).", "en": "Almost formulaic in the titles and comments of rec-request posts (저녁 메뉴 ㅊㅊ = \"dinner recs?\"). Because it splits three ways, learners are better off writing 추천해줘 in full when unsure. There is no paired opposite; to pan something people use ㅂㅊ (비추, \"not recommended\").", "es": "Casi una fórmula en títulos y comentarios de hilos de recomendaciones (저녁 메뉴 ㅊㅊ = \"¿qué ceno?\"). Como se bifurca en tres, a los estudiantes les conviene escribir 추천해줘 entero si dudan. No tiene opuesto emparejado; para desaconsejar se usa ㅂㅊ (비추).", "ja": "おすすめを募る投稿のタイトルやコメントでほぼ定型句のように使う(저녁 메뉴 ㅊㅊ=「夕飯のおすすめ」)。意味が三つに割れる初声なので、学習者は迷ったら「추천해줘」と普通に書くのが無難。対になる反対語はなく、良くないときはㅂㅊ(비추)を使う。", "vi": "Gần như công thức trong tiêu đề và bình luận bài xin gợi ý (저녁 메뉴 ㅊㅊ = \"gợi ý món tối\"). Vì tách ba nghĩa, người học nên viết đủ 추천해줘 khi không chắc. Không có từ trái nghĩa đi cặp; muốn chê thì dùng ㅂㅊ (비추)."}'::jsonb, array['ㅊㅋ', 'ㅇㅈ', '최애', '인생 맛집']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Recommend / Recs please"}, {"lang": "🇯🇵 JA", "text": "おすすめ / 推薦"}, {"lang": "🇨🇳 ZH", "text": "推荐"}, {"lang": "🇻🇳 VI", "text": "Giới thiệu / Gợi ý với"}, {"lang": "🇪🇸 ES", "text": "Recomiendo / Recomendaciones"}, {"lang": "🇩🇪 DE", "text": "Empfehlung / Empfehlt mir was"}]'::jsonb);

commit;
